package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Stream;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;
import org.junit.jupiter.api.io.TempDir;

class MashToolsCliTest {
    @TempDir static Path temporary;
    private static Path examples;
    private static final Runnable CHECK=()->{};
    private record Run(int code,String out,String err) { }
    private static Run run(String...args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=JLinAlgCli.run(Stream.concat(Stream.of("mashr-tools"),Stream.of(args)).toArray(String[]::new),new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Run(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    private static Path examples()throws IOException {if(examples==null){examples=temporary.resolve("exported");var exported=run("--export-example",examples.toString());assertEquals(0,exported.code(),exported.err());}return examples;}
    private static void copy(Path source,Path target)throws IOException {try(var files=Files.walk(source)){for(Path path:files.toList()){Path to=target.resolve(source.relativize(path));if(Files.isDirectory(path))Files.createDirectories(to);else Files.copy(path,to);}}}
    private static Path input(String name)throws IOException {Path input=temporary.resolve(name+"-input");copy(examples().resolve("fit-input"),input);return input;}
    private static Path admitted(String name)throws IOException {Path input=input(name),root=temporary.resolve(name);Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(0,result.code(),result.err());assertTrue(Files.isRegularFile(root.resolve("COMPLETED.json")));assertFalse(Files.exists(root.resolve("FAILURE.json")));return root;}
    private static void change(Path input,String key,String value)throws IOException {Path file=input.resolve("settings.tsv");var lines=new ArrayList<>(Files.readAllLines(file));for(int i=1;i<lines.size();i++)if(lines.get(i).startsWith(key+"\t")){lines.set(i,key+"\t"+value);Files.write(file,lines);return;}throw new AssertionError("Missing fixture setting "+key);}
    private static Map<String,Object> map(Object value){assertInstanceOf(Map.class,value);var result=new LinkedHashMap<String,Object>();for(var entry:((Map<?,?>)value).entrySet()){assertInstanceOf(String.class,entry.getKey());result.put((String)entry.getKey(),entry.getValue());}return result;}
    private static Map<String,Object> json(Path path)throws IOException {return map(MashFiles.json(path,8_388_608));}
    private static void write(Path path,Object value)throws IOException {Files.writeString(path,MashJson.json(value)+"\n",StandardCharsets.UTF_8);}
    private static void hashManifest(Path root)throws IOException {var files=new TreeMap<>(MashFiles.inventory(root,MashLimits.defaults(),CHECK).files());files.remove("SHA256SUMS");StringBuilder text=new StringBuilder();for(var item:files.entrySet())text.append(item.getValue().sha256()).append("  ").append(item.getKey()).append('\n');Files.writeString(root.resolve("SHA256SUMS"),text,StandardCharsets.UTF_8);}
    private static void reseal(Path root)throws IOException {
        hashManifest(root.resolve("execution/model"));hashManifest(root.resolve("execution"));
        var manifest=json(root.resolve("manifest.json"));var census=MashFiles.inventory(root,MashLimits.defaults(),CHECK);var files=new TreeMap<>(census.files());files.remove("manifest.json");files.remove("COMPLETED.json");manifest.put("files",files);manifest.put("directories",new java.util.TreeSet<>(census.directories()));write(root.resolve("manifest.json"),manifest);
        var marker=json(root.resolve("COMPLETED.json"));marker.put("manifest",MashFiles.pin(root.resolve("manifest.json"),8_388_608,CHECK));write(root.resolve("COMPLETED.json"),marker);
    }
    private static void rejected(Path root)throws IOException {var before=MashFiles.inventory(root,MashLimits.defaults(),CHECK);Run result=run("--verify",root.toString());assertEquals(2,result.code(),result.out());assertTrue(result.err().contains("FAIL2"),result.err());assertTrue(result.err().contains("Required action"));assertEquals(before,MashFiles.inventory(root,MashLimits.defaults(),CHECK));assertFalse(Files.exists(root.resolve("FAILURE.json")));}
    @Test void publicHelpAndExampleAreAvailableWithoutRunningAnalysis()throws Exception {var help=run("--help");assertEquals(0,help.code());assertTrue(help.out().contains("--verify"));assertTrue(help.out().contains("SKIP3"));assertTrue(help.out().contains("FAIL2"));Path root=examples();assertEquals("feature\tA\tB\n0001\t10\t10\n",Files.readString(root.resolve("fit-input/effects.tsv")));assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.readString(root.resolve("README.md")).contains("execution/model"));}
    @Test void trueSingletonIsAdmittedOnlyAfterCompleteReplay()throws Exception {
        Path root=admitted("singleton");var checked=MashBundle.verify(root,"COMPLETED.json",CHECK);assertTrue(checked.replay().numericValues()>30);assertEquals(0,checked.replay().maximumAbsoluteError());
        assertEquals(List.of("0001"),Files.readAllLines(root.resolve("execution/training-ids.tsv")));double value=Double.parseDouble(Files.readString(root.resolve("execution/posterior/mean.tsv")).split("\t")[0]);assertEquals(2000./201,value,1e-10);
        assertEquals(Boolean.FALSE,json(root.resolve("COMPLETED.json")).get("original_tool_executed"));assertTrue(Files.readString(root.resolve("execution/result.tsv")).contains("public_bundle_admitted\tfalse"));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("stage alone"));assertEquals(0,run("--verify",root.toString()).code());
    }
    @Test void portableVerificationDoesNotAccessTheProducerInputs()throws Exception {Path root=admitted("portable"),source=temporary.resolve("portable-input"),retained=temporary.resolve("portable-input-retained");assertTrue(source.toRealPath().startsWith(temporary.toRealPath()));assertTrue(retained.toAbsolutePath().startsWith(temporary.toAbsolutePath()));Files.move(source,retained);assertFalse(Files.exists(source));assertEquals(0,run("--verify",root.toString()).code());}
    @Test void admittedModelIsReusableByASeparatePublicPrediction()throws Exception {Path root=admitted("fit-for-prediction"),request=temporary.resolve("predict-input");copy(examples().resolve("predict-input"),request);copy(root.resolve("execution/model"),request.resolve("model"));Path result=temporary.resolve("prediction");var ran=run("--input",request.toString(),"--out",result.toString());assertEquals(0,ran.code(),ran.err());assertEquals(0,run("--verify",result.toString()).code());assertTrue(Files.readString(result.resolve("execution/result.tsv")).contains("training_rows\t0"));assertTrue(Files.readString(result.resolve("execution/result.tsv")).contains("IMPORTED_EXPANDED_MODEL"));}
    @Test void defaultLimitsRoundTripAndUnknownLimitsAreRejected()throws Exception {Run defaults=run("--default-limits");assertEquals(0,defaults.code());assertEquals(MashLimits.defaults(),MashLimits.parse(SimpleJson.parse(defaults.out())));var limits=map(SimpleJson.parse(defaults.out()));limits.put("unreviewed",true);Path file=temporary.resolve("unknown-limits.json");write(file,limits);Path output=temporary.resolve("bad-limits");Run result=run("--input",input("bad-limits").toString(),"--out",output.toString(),"--limits",file.toString());assertEquals(2,result.code());assertTrue(Files.readString(output.resolve("WARNINGS.md")).contains("FAIL2"));assertFalse(Files.exists(output.resolve("COMPLETED.json")));}
    @Test void unavailableLearningSkipsWithoutInventingNativeCovariances()throws Exception {Path input=input("unavailable");change(input,"basis","canonical_pca_ed");Path root=temporary.resolve("unavailable");Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(3,result.code(),result.err());assertTrue(result.err().contains("SKIP3"));assertTrue(result.err().contains("skip dependent analysis"));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("ANALYSIS SKIPPED"));assertFalse(Files.exists(root.resolve("execution")));assertFalse(Files.exists(root.resolve("COMPLETED.json")));}
    @Test void invalidSeFailsAndPreservesBothLayersOfDiagnostics()throws Exception {Path input=input("invalid-se");Files.writeString(input.resolve("standard-errors.tsv"),"feature\tA\tB\n0001\t0\t1\n");Path root=temporary.resolve("invalid-se");Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(2,result.code());assertTrue(result.err().contains("FAIL2"));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("Required action"));assertTrue(Files.exists(root.resolve("execution/FAILURE.txt")));assertFalse(Files.exists(root.resolve("COMPLETED.json")));}
    @Test void explicitOutputQuotaCannotProduceAnAdmittedPrefix()throws Exception {var limits=MashLimits.defaults();var execution=limits.execution();var tiny=new MashLimits(new MashNativeExecution.Limits(execution.rows(),execution.inputBytes(),1024,execution.fit()),limits.bundleBytes(),limits.entries());Path file=temporary.resolve("quota.json");write(file,tiny);Path root=temporary.resolve("quota");Run result=run("--input",input("quota").toString(),"--out",root.toString(),"--limits",file.toString());assertEquals(2,result.code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.isRegularFile(root.resolve("FAILURE.json")));}
    @Test void overlapAndExistingOutputsArePreserved()throws Exception {Path input=input("preserved"),overlap=input.resolve("output");assertEquals(2,run("--input",input.toString(),"--out",overlap.toString()).code());assertFalse(Files.exists(overlap));Path root=temporary.resolve("existing");Files.createDirectory(root);Files.writeString(root.resolve("sentinel"),"preserve");assertEquals(2,run("--input",input.toString(),"--out",root.toString()).code());assertEquals("preserve",Files.readString(root.resolve("sentinel")));try(var files=Files.list(root)){assertEquals(1,files.count());}}
    @Test void cancellationFailsWithoutAdmittingCompletedStageRecords()throws Exception {Path input=input("cancel"),root=temporary.resolve("cancel");Run result;Thread.currentThread().interrupt();try{result=run("--input",input.toString(),"--out",root.toString());}finally{Thread.interrupted();}assertEquals(2,result.code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("Required action"));}
    @TestFactory Stream<DynamicTest> changedScientificOrIdentityEvidenceCannotBeResealedIntoSuccess(){
        var tests=new ArrayList<DynamicTest>();for(String name:List.of("mean","covariance","weights","history","iterations","identity","model","truncated"))tests.add(DynamicTest.dynamicTest("resealed-"+name,()->{
            Path root=admitted("resealed-"+name);Path execution=root.resolve("execution");switch(name){
                case "mean"->alterCell(execution.resolve("posterior/mean.tsv"),0,.25);
                case "covariance"->alterCell(execution.resolve("posterior/covariance-column-major.tsv"),0,.25);
                case "weights"->alterCell(execution.resolve("posterior/weights.tsv"),0,.25);
                case "history"->alterCell(execution.resolve("fit/weights-0/history.tsv"),1,.25);
                case "iterations"->{Path path=execution.resolve("fit/weights-0/diagnostics.tsv");String text=Files.readString(path);String iteration=text.lines().filter(x->x.startsWith("iterations\t")).findFirst().orElseThrow();Files.writeString(path,text.replace(iteration,"iterations\t999"));}
                case "identity"->Files.writeString(execution.resolve("target-ids.tsv"),"1\n");
                case "model"->alterCell(execution.resolve("model/component-2.tsv"),0,-1);
                case "truncated"->Files.writeString(execution.resolve("posterior/mean.tsv"),"");
                default->throw new AssertionError();
            }reseal(root);rejected(root);
        }));return tests.stream();
    }
    private static void alterCell(Path path,int row,double change)throws IOException {var lines=new ArrayList<>(Files.readAllLines(path));String[] values=lines.get(row).split("\t");int column=path.getFileName().toString().equals("history.tsv")?1:0;values[column]=Double.toString(Double.parseDouble(values[column])+change);lines.set(row,String.join("\t",values));Files.write(path,lines);}
    @Test void explicitNumericToleranceIsBoundedAndReported()throws Exception {Path root=admitted("roundoff");alterCell(root.resolve("execution/posterior/mean.tsv"),0,5e-12);reseal(root);var checked=MashBundle.verify(root,"COMPLETED.json",CHECK);assertTrue(checked.replay().maximumAbsoluteError()>0);assertTrue(checked.replay().maximumAbsoluteError()<1e-10);assertTrue(checked.replay().numericValues()>30);}
    @Test void addedEmptyDirectoryCannotHideInAResealedCensus()throws Exception {Path root=admitted("empty-dir");Files.createDirectory(root.resolve("unexplained"));reseal(root);rejected(root);}
    @Test void requiredWarningsCannotBeRemovedEvenWithNewHashes()throws Exception {Path root=admitted("warnings");Files.writeString(root.resolve("WARNINGS.md"),"looks complete\n");reseal(root);rejected(root);}
    @Test void upstreamExecutionClaimsCannotBeForgedIntoNativeCompletion()throws Exception {Path root=admitted("claims");var marker=json(root.resolve("COMPLETED.json"));marker.put("original_tool_executed",true);write(root.resolve("COMPLETED.json"),marker);rejected(root);}
    @Test void provisionalMarkerCannotStandInForTopLevelCompletion()throws Exception {Path root=admitted("provisional");Files.move(root.resolve("COMPLETED.json"),root.resolve("COMPLETION-PROVISIONAL.json"));assertEquals(2,run("--verify",root.toString()).code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));}
    @Test void verificationCancellationLeavesTheSourceUnchanged()throws Exception {Path root=admitted("cancel-verify");var before=MashFiles.inventory(root,MashLimits.defaults(),CHECK);assertThrows(java.util.concurrent.CancellationException.class,()->MashBundle.verify(root,"COMPLETED.json",()->{throw new java.util.concurrent.CancellationException("stop");}));assertEquals(before,MashFiles.inventory(root,MashLimits.defaults(),CHECK));}
    private static Path nullInput(String name,String mode,double[][] effects,double rho)throws IOException {
        Path input=input(name);StringBuilder bhat=new StringBuilder("feature\tA\tB\n"),se=new StringBuilder("feature\tA\tB\n"),population=new StringBuilder("feature\ttrain\tstrong\ttarget\n");
        for(int i=0;i<effects.length;i++){String id="null-"+i;bhat.append(id).append('\t').append(effects[i][0]).append('\t').append(effects[i][1]).append('\n');se.append(id).append("\t1\t1\n");population.append(id).append("\t1\t0\t0\n");}
        bhat.append("target\t0.1\t-0.2\n");se.append("target\t1\t1\n");population.append("target\t0\t0\t1\n");Files.writeString(input.resolve("effects.tsv"),bhat);Files.writeString(input.resolve("standard-errors.tsv"),se);Files.writeString(input.resolve("populations.tsv"),population);
        Files.writeString(input.resolve("basis/component-1.tsv"),"0\t0\n0\t0\n");Files.writeString(input.resolve("residual.tsv"),"1\t"+rho+"\n"+rho+"\t1\n");change(input,"point_mass","false");change(input,"prior","uniform");change(input,"residual",mode);change(input,"residual_tolerance","1e-10");return input;
    }
    @Test void publicCovarianceEmReplaysEveryProposalAndWeightHistory()throws Exception {Path input=nullInput("public-em","em_covariance",new double[][]{{1,0},{0,2},{-1,0},{0,-2}},0),root=temporary.resolve("public-em");Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(0,result.code(),result.err());assertEquals(0,run("--verify",root.toString()).code());assertEquals(.5,Double.parseDouble(Files.readAllLines(root.resolve("execution/model/residual.tsv")).get(0).split("\t")[0]),1e-12);assertTrue(Files.exists(root.resolve("execution/fit/proposal-1/residual.tsv")));assertTrue(Files.exists(root.resolve("execution/fit/weights-1/history.tsv")));}
    @Test void publicResidualRollbackRetainsTheRejectedProposalAndWarns()throws Exception {Path input=nullInput("public-rollback","em_correlation",new double[][]{{Math.sqrt(8),Math.sqrt(2)},{-Math.sqrt(8),-Math.sqrt(2)},{0,Math.sqrt(6)},{0,-Math.sqrt(6)}},.3),root=temporary.resolve("public-rollback");Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(0,result.code(),result.err());assertTrue(result.err().contains("RESIDUAL_ROLLBACK"));assertTrue(Files.readString(root.resolve("execution/fit/step-1.tsv")).contains("accepted\tfalse"));assertEquals(.3,Double.parseDouble(Files.readAllLines(root.resolve("execution/model/residual.tsv")).get(0).split("\t")[1]),1e-12);assertEquals(0,run("--verify",root.toString()).code());}
    @Test void publicSimpleNullCovarianceKeepsTheCompleteSelectedPopulation()throws Exception {Path input=nullInput("public-simple","simple",new double[][]{{1,0},{0,2},{-1,0},{0,-2}},0),root=temporary.resolve("public-simple");Files.delete(input.resolve("residual.tsv"));Files.writeString(input.resolve("settings.tsv"),"null_z_threshold\t3\nnull_correlation\tfalse\n",java.nio.file.StandardOpenOption.APPEND);Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(0,result.code(),result.err());assertEquals(List.of("null-0","null-1","null-2","null-3"),Files.readAllLines(root.resolve("execution/fit/null-selected-ids.tsv")));assertEquals(0,run("--verify",root.toString()).code());}
    @Test void publicResidualExhaustionKeepsCandidatesWithoutAdmittingThem()throws Exception {Path input=nullInput("public-em-limit","em_covariance",new double[][]{{1,0},{0,2},{-1,0},{0,-2}},0),root=temporary.resolve("public-em-limit");change(input,"residual_maxiter","1");change(input,"residual_tolerance","0");Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(2,result.code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.exists(root.resolve("execution/fit/weights-1/proportions.tsv")));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("RESIDUAL_LIMIT"));}
    @Test void publicWeightExhaustionKeepsTheFullFailedHistory()throws Exception {Path input=input("public-weight-limit"),root=temporary.resolve("public-weight-limit");Files.writeString(input.resolve("effects.tsv"),"feature\tA\tB\n0001\t1\t1\n");Files.writeString(input.resolve("basis/component-names.tsv"),"first\nsecond\n");Files.writeString(input.resolve("basis/component-1.tsv"),".1\t0\n0\t.1\n");Files.writeString(input.resolve("basis/component-2.tsv"),".11\t0\n0\t.11\n");change(input,"point_mass","false");change(input,"prior","uniform");change(input,"weight_maxiter","1");change(input,"weight_dual_gap","1e-12");Run result=run("--input",input.toString(),"--out",root.toString());assertEquals(2,result.code());assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.exists(root.resolve("execution/fit/weights-0/history.tsv")));assertTrue(Files.readString(root.resolve("WARNINGS.md")).contains("WEIGHTS_NONCONVERGED"));}
    @Test void aLateChangedOutputCannotLeaveAnAdmittedCompletionMarker()throws Exception {
        Path input=input("late-change"),root=temporary.resolve("late-change");MashFiles.create(root);var changed=new java.util.concurrent.atomic.AtomicBoolean();
        IOException failure=assertThrows(IOException.class,()->MashBundle.produce(root,input,(MashJson.json(MashLimits.defaults())+"\n").getBytes(StandardCharsets.UTF_8),()->{
            if(Files.exists(root.resolve("COMPLETED.json"))&&changed.compareAndSet(false,true))try{alterCell(root.resolve("execution/posterior/mean.tsv"),0,.25);}catch(IOException error){throw new java.io.UncheckedIOException(error);}
        }));
        assertTrue(changed.get());assertTrue(failure.getMessage().contains("finalization"));assertFalse(Files.exists(root.resolve("COMPLETED.json")));assertTrue(Files.exists(root.resolve("execution/posterior/mean.tsv")));
    }
}
